const input = $input.first().json;
const body = input.body ?? input;

const requiredFields = [
  'change_id',
  'specification_path',
];

const missingFields = requiredFields.filter(field => {
  const value = body[field];

  return (
    typeof value !== 'string' ||
    value.trim() === ''
  );
});

if (missingFields.length > 0) {
  throw new Error(
    `Campos obrigatórios ausentes: ${missingFields.join(', ')}`
  );
}

const event = body.event ?? 'submit_for_analysis';

if (event !== 'submit_for_analysis') {
  throw new Error(`Evento não suportado: ${event}`);
}

const specificationPath = body.specification_path.trim();

const specificationMatch = specificationPath.match(
  /^docs\/specs\/([A-Za-z0-9]+(?:-[A-Za-z0-9]+)*)\.md$/
);

if (!specificationMatch) {
  throw new Error(
    'O caminho deve seguir docs/specs/<Nome>.md, ' +
    'com segmentos alfanuméricos separados por hífen.'
  );
}

const specificationName = specificationMatch[1];
const branchSlug = specificationName.toLowerCase();
const workingBranch = `spec/${branchSlug}`;

return [
  {
    json: {
      event,
      source: body.source ?? 'repository_command',

      change_id: body.change_id.trim(),
      specification_path: specificationPath,

      repository_owner: 'iotsmartsys',
      repository_name: 'IoTSmartLink15.4',

      working_branch: workingBranch,
      branch_source: 'specification_path',

      revision:
        typeof body.revision === 'string' &&
        body.revision.trim() !== ''
          ? body.revision.trim()
          : null,

      submitted_by:
        typeof body.submitted_by === 'string' &&
        body.submitted_by.trim() !== ''
          ? body.submitted_by.trim()
          : 'not_informed',

      received_at: new Date().toISOString(),

      phase: 'analysis',
      allow_code_changes: false,
      allow_main_changes: false,
      require_architect_approval: true,
    },
  },
];

const input = $input.first().json;
const body = input.body ?? input;

function requiredString(value, field) {
  if (typeof value !== 'string' || !value.trim()) {
    throw new Error(`Campo obrigatório inválido: ${field}`);
  }

  if (/[\r\n]/.test(value)) {
    throw new Error(`O campo ${field} deve ocupar uma única linha`);
  }

  return value.trim();
}

const event = requiredString(body.event, 'event');
const source = requiredString(body.source, 'source');
const workingBranch = requiredString(
  body.working_branch,
  'working_branch'
);
const authorizedBy = requiredString(
  body.authorized_by,
  'authorized_by'
);

if (event !== 'submit_for_implementation') {
  throw new Error(`Evento não suportado: ${event}`);
}

if (source !== 'repository_command') {
  throw new Error(`Origem não suportada: ${source}`);
}

if (!/^spec\/[a-z0-9]+(?:-[a-z0-9]+)*$/.test(workingBranch)) {
  throw new Error(
    `Branch incompatível com a convenção EKOM: ${workingBranch}`
  );
}

if (body.allow_tests !== false) {
  throw new Error('Este piloto não autoriza testes');
}

if (body.allow_hardware !== false) {
  throw new Error('Este piloto não autoriza hardware');
}

return [
  {
    json: {
      event,
      source,
      working_branch: workingBranch,
      architect_authorization: true,
      authorized_by: authorizedBy,
      allow_tests: false,
      allow_hardware: false,
      received_at: new Date().toISOString(),
    },
  },
];
